     7→import { Button, Input } from "shared/components";
     8→import { Colors } from "shared/styles";
     9→import { InputMessagePayload } from "../input-message-payload";
    10→import { SendItemsList } from "../send-items-list";
    11→import { VoiceRecordButton } from "../voice-record-button";
