    17→const sendButtonTransition = animateParallel(
    18→  { opacity: [0, 1], width: [0, 56] },
    19→  { duration: 200, native: false },
    20→);
    21→
    22→const imageTransition = animateParallel(
    23→  { opacity: [0, 1], width: [0, 48] },
    24→  { duration: 200, native: false },
    25→);
    26→
    27→const inputTransition = animateParallel(
    28→  { opacity: [0, 1], width: ["0%", "100%"] },
