    32→export const RoomInput: FC<Props> = ({ roomId }) => {
    33→  const [message, setMessage] = useState("");
    34→  const [isRecording, setIsRecording] = useState(false);
    35→  const [isRecorded, setIsRecorded] = useState(false);
    36→  const [replyPayload, setReplyPayload] = useAtom(TimelineAtoms.replyPayload);
    37→  const [editPayload, setEditPayload] = useAtom(TimelineAtoms.editPayload);
    38→  const hasPayload = !!replyPayload || !!editPayload;
    39→
    40→  const handleSendMessage = async () => {
    41→    if (!message) return;
    42→
    43→    try {
    44→      if (editPayload) {
    45→        await MatrixService.editMessage(roomId, editPayload.event, message);
    46→        setEditPayload(null);
    47→        return;
    48→      }
    49→
    50→      if (replyPayload) {
    51→        await MatrixService.replyToMessage(
    52→          roomId,
    53→          message,
    54→          replyPayload.eventId,
    55→        );
