## COMPREHENSIVE FILE ANALYSIS FOR IDENTITY RESET DETECTION UI PLANNING

### 1. `/src/screens/room/Room.tsx` (FULL)

```typescript
import { Screen } from "@prototyp/skeletor";
import { useIsFocused } from "@react-navigation/native";
import type { NativeStackScreenProps } from "@react-navigation/native-stack";
import { Membership, type RoomInfo } from "@unomed/react-native-matrix-sdk";
import { MatrixService } from "modules/matrix-client/services";
import { useRoomInitialization } from "modules/timeline/hooks";
import { useEffect, useMemo, useState } from "react";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { Loading } from "shared/components";
import { RoomHeader, RoomInvite, RoomTimeline } from "./fragments";

export const Room: React.FC<NativeStackScreenProps<Routes, "room">> = ({
  route,
  navigation,
}) => {
  const { roomId } = route.params;
  const client = MatrixService.instance;
  const isFocused = useIsFocused();
  const room = useMemo(() => client?.getRoom(roomId), [client, roomId]);
  const insets = useSafeAreaInsets();
  const hasActiveCall = useMemo(
    () => room?.hasActiveRoomCall(),
    [room, isFocused],
  );
  const [roomInfo, setRoomInfo] = useState<RoomInfo | undefined>(undefined);
  const [isInviteAccepted, setIsInviteAccepted] = useState(false);
  const isRoomInvite = useMemo(() => {
    return roomInfo?.membership === Membership.Invited && !isInviteAccepted;
  }, [roomInfo, isInviteAccepted]);

  const { isMembersLoading, roomMembers, hasNoCallOption } =
    useRoomInitialization({ room });

  useEffect(() => {
    room?.roomInfo().then(setRoomInfo).catch(console.error);
  }, [room]);

  const handleStartCall = () => {
    if (!client || !room) {
      console.error("Client or room not available");
      return;
    }

    navigation.navigate("elementCall", {
      roomId,
      roomName: room.displayName(),
    });
  };

  const handleInviteAccepted = () => {
    setIsInviteAccepted(true);
  };

  const handleInviteDeclined = () => {
    navigation.goBack();
  };

  const handleRoomDetails = () => {
    if (isRoomInvite || !room) return;
    navigation.navigate("roomDetails", { room });
  };

  if (!room) return null;

  if (!roomInfo) {
    return (
      <Screen hideTopSafeArea scrollable={false}>
        <RoomHeader
          room={room}
          isMembersLoading={isMembersLoading}
          roomMembers={roomMembers}
          hasActiveCall={false}
          hasNoCallOption
          topInset={insets.top}
          onBack={() => navigation.goBack()}
        />
        <Loading isFullScreen={false} />
      </Screen>
    );
  }

  return (
    <Screen hideTopSafeArea>
      <RoomHeader
        room={room}
        isMembersLoading={isMembersLoading}
        roomMembers={roomMembers}
        hasActiveCall={hasActiveCall ?? false}
        hasNoCallOption={isRoomInvite || hasNoCallOption}
        topInset={insets.top}
        onBack={() => navigation.goBack()}
        onRoomDetails={handleRoomDetails}
        onStartCall={handleStartCall}
      />

      {isRoomInvite ? (
        <RoomInvite
          roomId={roomId}
          roomInfo={roomInfo}
          onAccepted={handleInviteAccepted}
          onDeclined={handleInviteDeclined}
        />
      ) : (
        <RoomTimeline room={room} roomId={roomId} />
      )}
    </Screen>
  );
};
```

**Key Patterns:**
- Uses `MatrixService.instance` for client access
- Fragment-based composition (RoomHeader, RoomInvite, RoomTimeline)
- Room-level state management for invite acceptance
- Safe area insets handling via `useSafeAreaInsets()`

---

### 2. `/src/screens/room/fragments/room-timeline/RoomTimeline.tsx` (FULL)

```typescript
import { Block, Text } from "@prototyp/skeletor";
import type { RoomInterface } from "@unomed/react-native-matrix-sdk";
import { useAtom } from "jotai";
import { addDateDividers, getEventId } from "modules/matrix-client/utils";
import { useRoomTimeline } from "modules/timeline/hooks";
import { TimelineAtoms } from "modules/timeline/jotai";
import {
  filterSameStateKey,
  handleIsPreviousSameSender,
} from "modules/timeline/utils";
import {
  type FC,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  FlatList,
  Image,
  KeyboardAvoidingView,
  type NativeScrollEvent,
  type NativeSyntheticEvent,
  StyleSheet,
} from "react-native";
import {
  Button,
  ImageViewerModal,
  Loading,
  MemberDetailsBottomSheet,
  VideoViewerModal,
} from "shared/components";
import { useMemberDetails } from "shared/hooks";
import { DateDivider } from "../date-divider";
import { MessageContentBottomSheet } from "../message-content-bottom-sheet";
import { RoomInput } from "../room-input";
import { SingleMessageType } from "../single-message-type";

interface Props {
  room: RoomInterface;
  roomId: string;
}

export const RoomTimeline: FC<Props> = ({ room, roomId }) => {
  const flatListRef = useRef<FlatList>(null);
  const isAtBottomRef = useRef(true);
  const [showScrollDown, setShowScrollDown] = useState(false);
  const {
    events,
    loadingMessage,
    refreshing,
    updateTrigger,
    isDirect,
    loadMoreMessages,
    markAsRead,
  } = useRoomTimeline({
    room,
    roomId,
  });
  const [scrollToEventId, setScrollToEventId] = useAtom(
    TimelineAtoms.scrollToEventId,
  );
  const {
    selectedMember,
    isBottomSheetOpen,
    openMemberDetails,
    closeMemberDetails,
  } = useMemberDetails();

  const sortedEvents = useMemo(() => {
    const sorted = [...events].sort(
      (a, b) => Number(a.timestamp) - Number(b.timestamp),
    );

    return filterSameStateKey(sorted);
  }, [events]);

  const eventsWithDividers = useMemo(() => {
    return addDateDividers(sortedEvents);
  }, [sortedEvents]);

  const handleScrollToEvent = useCallback(
    (eventId: string) => {
      const index = eventsWithDividers.findIndex(
        (item) => item.type === "event" && getEventId(item.data) === eventId,
      );
      if (index === -1) return;

      flatListRef.current?.scrollToIndex({
        index,
        animated: true,
        viewPosition: 0.5,
      });
    },
    [eventsWithDividers],
  );

  useEffect(() => {
    if (!scrollToEventId) return;
    handleScrollToEvent(scrollToEventId);
    setScrollToEventId(null);
  }, [scrollToEventId, handleScrollToEvent, setScrollToEventId]);

  const handleLoadMore = async () => {
    setShowScrollDown(false);
    await loadMoreMessages();
  };

  const handleContentSizeChange = () => {
    const lastEvent = sortedEvents[sortedEvents.length - 1];
    if (!isAtBottomRef.current && !lastEvent?.isOwn) return;
    flatListRef.current?.scrollToEnd({ animated: false });
    setTimeout(() => {
      flatListRef.current?.scrollToEnd({ animated: false });
    }, 100);
  };

  const handleScrollDown = () => {
    flatListRef.current?.scrollToEnd({ animated: true });
    setShowScrollDown(false);
  };

  const handleOnScroll = ({
    nativeEvent,
  }: NativeSyntheticEvent<NativeScrollEvent>) => {
    const { layoutMeasurement, contentOffset, contentSize } = nativeEvent;
    const paddingToBottom = 100;
    const atBottom =
      layoutMeasurement.height + contentOffset.y >=
      contentSize.height - paddingToBottom;
    isAtBottomRef.current = atBottom;
    if (!atBottom) return;
    setShowScrollDown(false);
    markAsRead();
  };

  useEffect(() => {
    const lastEvent = sortedEvents[sortedEvents.length - 1];
    if (isAtBottomRef.current || lastEvent?.isOwn) return;

    setShowScrollDown(true);
  }, [isAtBottomRef.current, sortedEvents]);

  if (loadingMessage) {
    return (
      <Block flex={1} align="center" justify="center">
        <Loading isFullScreen={false} />
      </Block>
    );
  }

  return (
    <>
      <KeyboardAvoidingView style={styles.flex} behavior="padding">
        <FlatList
          ref={flatListRef}
          data={eventsWithDividers}
          keyExtractor={(item) => {
            if (item.type === "divider") return item.id;

            return getEventId(item.data) ?? "";
          }}
          extraData={updateTrigger}
          contentContainerStyle={styles.listContent}
          refreshing={refreshing}
          onContentSizeChange={handleContentSizeChange}
          onRefresh={handleLoadMore}
          onScroll={handleOnScroll}
          onScrollToIndexFailed={(info) => {
            flatListRef.current?.scrollToOffset({
              offset: info.averageItemLength * info.index,
              animated: true,
            });
          }}
          renderItem={({ item }) => {
            if (item.type === "divider") {
              return <DateDivider date={item.date} />;
            }

            const eventIndex = sortedEvents.findIndex(
              (e) => getEventId(e) === getEventId(item.data),
            );

            return (
              <SingleMessageType
                event={item.data}
                isPreviousSameSender={handleIsPreviousSameSender(
                  isDirect,
                  sortedEvents,
                  item.data,
                  eventIndex,
                )}
                onMemberPress={openMemberDetails}
              />
            );
          }}
        />

        <RoomInput roomId={roomId} />
      </KeyboardAvoidingView>

      <MessageContentBottomSheet roomId={roomId} />

      <MemberDetailsBottomSheet
        isBottomSheetOpen={isBottomSheetOpen}
        selectedMember={selectedMember}
        roomId={roomId}
        onClose={closeMemberDetails}
      />

      {showScrollDown && (
        <Block
          absolute
          offsets={{ right: 0, bottom: 100 }}
          align="center"
          justify="center"
          width="100%"
        >
          <Button.Outline size="medium" onPress={handleScrollDown}>
            <Text>New messages</Text>
            <Image source={require("assets/icons/arrow-down.png")} />
          </Button.Outline>
        </Block>
      )}

      <ImageViewerModal />
      <VideoViewerModal />
    </>
  );
};

const styles = StyleSheet.create({
  flex: {
    flex: 1,
  },
  listContent: {
    paddingHorizontal: 20,
    paddingTop: 12,
    paddingBottom: 20,
  },
});
```

**Key Patterns:**
- FlatList with events, dividers, and scroll management
- Jotai atoms for event scrolling (TimelineAtoms.scrollToEventId)
- Modal overlays for images, videos, member details, and message content
- Custom hook pattern: `useRoomTimeline()` returns events and actions
- Utility functions for event filtering and sender comparison

