### 3. `/src/screens/room/fragments/room-input/RoomInput.tsx` (FULL)

```typescript
import { animateParallel, Block } from "@prototyp/skeletor";
import { useAtom } from "jotai";
import { MatrixService } from "modules/matrix-client/services";
import { TimelineAtoms } from "modules/timeline/jotai";
import { type FC, useEffect, useState } from "react";
import { Image } from "react-native";
import { Button, Input } from "shared/components";
import { Colors } from "shared/styles";
import { InputMessagePayload } from "../input-message-payload";
import { SendItemsList } from "../send-items-list";
import { VoiceRecordButton } from "../voice-record-button";

interface Props {
  roomId: string;
}

const sendButtonTransition = animateParallel(
  { opacity: [0, 1], width: [0, 56] },
  { duration: 200, native: false },
);

const imageTransition = animateParallel(
  { opacity: [0, 1], width: [0, 48] },
  { duration: 200, native: false },
);

const inputTransition = animateParallel(
  { opacity: [0, 1], width: ["0%", "100%"] },
  { duration: 200, native: false },
);

export const RoomInput: FC<Props> = ({ roomId }) => {
  const [message, setMessage] = useState("");
  const [isRecording, setIsRecording] = useState(false);
  const [isRecorded, setIsRecorded] = useState(false);
  const [replyPayload, setReplyPayload] = useAtom(TimelineAtoms.replyPayload);
  const [editPayload, setEditPayload] = useAtom(TimelineAtoms.editPayload);
  const hasPayload = !!replyPayload || !!editPayload;

  const handleSendMessage = async () => {
    if (!message) return;

    try {
      if (editPayload) {
        await MatrixService.editMessage(roomId, editPayload.event, message);
        setEditPayload(null);
        return;
      }

      if (replyPayload) {
        await MatrixService.replyToMessage(
          roomId,
          message,
          replyPayload.eventId,
        );
        setReplyPayload(null);
        return;
      }

      await MatrixService.sendMessage(roomId, message);
    } catch (error) {
      console.error("Failed to send message:", error);
    } finally {
      setMessage("");
    }
  };

  useEffect(() => {
    if (!editPayload) {
      setMessage("");
      return;
    }
    setMessage(editPayload.content);
  }, [editPayload]);

  useEffect(() => {
    if (message || replyPayload) {
      sendButtonTransition.start();
      imageTransition.reverse();
    } else {
      sendButtonTransition.reverse();
      imageTransition.start();
    }
  }, [message, replyPayload]);

  useEffect(() => {
    setReplyPayload(null);
    setEditPayload(null);
  }, [setEditPayload, setReplyPayload]);

  useEffect(() => {
    if (isRecording || isRecorded) {
      imageTransition.reverse();
      inputTransition.reverse();
    } else {
      imageTransition.start();
      inputTransition.start();
    }
  }, [isRecording, isRecorded]);

  return (
    <Block>
      <Block
        paddings={[20, 0, 20, 16]}
        flexDirection="row"
        align="flex-end"
        justify="space-between"
        height={hasPayload ? 158 : 88}
        gap={message || replyPayload ? 0 : 8}
      >
        <Block
          animations={imageTransition.animations}
          height={48}
          align="center"
          justify="center"
        >
          <SendItemsList roomId={roomId} />
        </Block>
        <VoiceRecordButton
          roomId={roomId}
          message={message}
          isRecording={isRecording}
          isRecorded={isRecorded}
          setIsRecorded={setIsRecorded}
          setIsRecording={setIsRecording}
        />
        <Block
          flex={isRecording || isRecorded ? 0 : 1}
          animations={inputTransition.animations}
          border={{ borderRadius: hasPayload ? 12 : 40 }}
          background={Colors.white5}
        >
          <InputMessagePayload />
          <Input
            placeholder="Message"
            value={message}
            background="transparent"
            autoCapitalize="none"
            onChangeText={(value) => setMessage(value)}
          />
        </Block>
        <Block
          animations={sendButtonTransition.animations}
          height={48}
          overflow="hidden"
        >
          <Button.Wrapper disabled={!message} onPress={handleSendMessage}>
            <Block
              height={48}
