  const { members, roomId } = route.params;
  const {
    selectedMember,
    isBottomSheetOpen,
    openMemberDetails,
    closeMemberDetails,
  } = useMemberDetails();
  const pendingMembers = members.filter(
    (member) => member.membership?.tag === MembershipState_Tags.Invite,
  );
  const acceptedMembers = members.filter(
    (member) => member.membership?.tag === MembershipState_Tags.Join,
  );
  const bannedMembers = members.filter(
    (member) => member.membership?.tag === MembershipState_Tags.Ban,
  );
  const [userPowerLevel, setUserPowerLevel] = useState<number | null>(null);
  const isModerator = useMemo(
    () => Number(userPowerLevel) >= 50,
    [userPowerLevel],
  );

  const sections = [
    {
      title: "Pending",
      data: pendingMembers,
    },
    {
      title: "",
      data: acceptedMembers,
    },
    {
      title: "Banned",
      data: bannedMembers,
    },
  ];

  const handleMemberPress = useCallback(
    (member: RoomMember) => {
      openMemberDetails({
        userId: member.userId,
        displayName: member.displayName ?? "Unknown",
